drop policy if exists "business_metric_leaderboards_select_authenticated" on public.business_metric_leaderboards; create policy "business_metric_leaderboards_select_scoped" on public.business_metric_leaderboards for select to authenticated using (exists(select 1 from public.business_members bm where bm.business_id=business_metric_leaderboards.business_id and bm.user_id=(select auth.uid())) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and coalesce(p.is_admin,false)));
drop policy if exists "partners_member_all" on public.partner_programs; create policy "partners_member_advanced_all" on public.partner_programs for all to authenticated using (exists(select 1 from public.business_members bm join public.businesses b on b.id=bm.business_id where bm.business_id=partner_programs.business_id and bm.user_id=(select auth.uid()) and bm.role=any(array['owner'::business_member_role,'admin'::business_member_role,'manager'::business_member_role]) and b.business_tier <> 'standard'::business_tier)) with check (exists(select 1 from public.business_members bm join public.businesses b on b.id=bm.business_id where bm.business_id=partner_programs.business_id and bm.user_id=(select auth.uid()) and bm.role=any(array['owner'::business_member_role,'admin'::business_member_role,'manager'::business_member_role]) and b.business_tier <> 'standard'::business_tier));
